const rotate = async (oldToken: string) => {
     const row = repo.findByHash(sha256(oldToken));
     if (!row || row.expires_at < Date.now() || repo.isFamilyRevoked(row.family_id)) {
       throw new InvalidToken();
     }
     if (row.revoked_at) {
       repo.revokeFamily(row.family_id);
       throw new TokenReuseDetected();
     }
     repo.revoke(row.id);
     const user = await users.findById(row.user_id);
     const access = await signAccessToken(user, row.family_id);
     const refresh = newRefreshToken();
     repo.insert({
       familyId: row.family_id,
       userId: user.id,
       hash: sha256(refresh),
       expiresAt: Date.now() + REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
     });
     return { access, refresh };
   };

const findByHash = (hash: string): RefreshTokenRow | undefined => {
     return db
       .prepare<[string], RefreshTokenRow>(
         "SELECT * FROM refresh_tokens WHERE token_hash = ?"
       )
       .get(hash);
   };

const revoke = (id: number): void => {
     db.prepare(
       "UPDATE refresh_tokens SET revoked_at = ? WHERE id = ?"
     ).run(Date.now(), id);
   };

const insert = (params: {
     familyId: string;
     userId: number;
     hash: string;
     expiresAt: number;
   }): void => {
     db.prepare(
       "INSERT INTO refresh_tokens (family_id, user_id, token_hash, created_at, expires_at) VALUES (?, ?, ?, ?, ?)"
     ).run(params.familyId, params.userId, params.hash, Date.now(), params.expiresAt);
   };

const refresh = async (req: Request, res: Response): Promise<void> => {
     const oldToken = (req.cookies as Record<string, string>)["rt"];
     if (!oldToken) {
       res.status(401).json({ error: "No refresh token" });
       return;
     }
     try {
       const { access, refresh: newRefresh } = await tokenService.rotate(oldToken);
       res.cookie("rt", newRefresh, {
         httpOnly: true,
         sameSite: "strict",
         maxAge: REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
       });
       res.json({ accessToken: access });
     } catch (err) {
       if (err instanceof InvalidToken || err instanceof TokenReuseDetected) {
         res.clearCookie("rt");
         res.status(401).json({ error: "Unauthorized" });
         return;
       }
       throw err;
     }
   };

export function openDb(path: string): Database.Database {
   const db = new Database(path);
   db.pragma("journal_mode = WAL");
   db.pragma("foreign_keys = ON");
   const migration = readFileSync(
     join(__dirname, "migrations", "001_init.sql"),
     "utf8"
   );
   db.exec(migration);
   return db;
}

